-- Refresh the verified product knowledge to the site as it is on 2026-10-12, from docs/distribution/PRODUCT_FACTS.md in the
-- fillbook repo (sections 3, 4, 6a to 6e), the Essentials plan code (frontend/src/lib/pricingTiers.ts) and the in-app
-- "What's new" entries through 2026-10-10.
--
--   pricing            The live entry (0046, 2026-09-25) still says Starter is the entry plan, there is no free plan and a
--                      lapsed trial goes read-only. None of that is true now: a permanent Free plan exists, Starter is
--                      retired for new signups, and Essentials ($14.99, for own-money traders) was added and renamed from
--                      "Own Capital" on 2026-10-11. Superseded, not deleted.
--   integrations       New. Which platforms sync, how, and what is still beta, so a reply never over- or under-states it.
--   what_fillbook_does New. The capabilities a reply may draw on, including everything added since 2026-09-25.
--
-- Not claimed anywhere below: live open P&L from the NinjaTrader add-on (#786 in the fillbook repo is unapplied and unverified
-- on a live NinjaTrader), the six API-broker connectors, Rithmic or DXtrade as available, ChatGPT connectors, user counts.
--
-- Additive and idempotent: the old pricing entry is marked 'deprecated' and points at its replacement; the other two are only
-- inserted when no verified entry for the topic exists. Growth OS migrations have no runner: the owner applies this by hand in
-- the Supabase SQL editor. The knowledge loader reads only trust_level = 'verified', so the swap happens in one statement.

with old_pricing as (
  select id from knowledge_documents where topic = 'pricing' and trust_level = 'verified' and superseded_by is null
), new_pricing as (
  insert into knowledge_documents (topic, title, content, source_doc, trust_level, effective_at)
  select 'pricing', 'Fillbook pricing plans (verified 2026-10-12)',
    $$Every new account gets a 14-day free trial, no card required, with Core-level access plus one supported auto-sync connection. AI features (the AI coach and chat, the weekly AI email review), the Discord recap and Trade Replay are not part of the trial. If the trial ends without a subscription, the account steps down to the permanent Free plan: it is not locked and not read-only. Plans are month to month and can be cancelled anytime. Free ($0): one account, CSV import and manual entry, unlimited logged trades, dashboard, calendar heatmap and equity curve, R-multiple, daily notes, and the drawdown, daily-loss and consistency buffer for that one account; no auto-sync, no breach alerts, no AI. Essentials ($14.99 a month): for traders funding their own futures account; adds the analytics pages to everything on Free (an own-capital account that logs deposits and withdrawals, up to 3 accounts, Find My Leaks, Edge Score, Account Health, Daily Brief, behavioral flags, playbooks, time-of-day breakdown, reflections, backtest, tax export and the trading simulator); it does NOT include broker auto-sync, breach alerts, payouts, Trade Replay, mentor links, the AI-assistant connector or any AI, which stay on Core and Elite. It was called Own Capital until 2026-10-11. Core ($24.99 a month): up to 5 accounts; everything in Free plus prop-firm rule tracking with an all-accounts overview and breach alerts, broker auto-sync, payout tracking and the account ledger, Trade Replay, the trading simulator, the Intelligence suite, the Discord daily recap, mentor links and the AI-assistant connection (beta). Elite ($39.99 a month): up to 50 accounts; everything in Core plus the AI coach and conversational AI, Behavior Replay, the weekly AI review email, a higher daily limit on manual Sync now pulls and on AI requests, and priority support. Starter ($12.99 a month) is retired for new signups; existing subscribers keep it, and it is never offered or listed. Annual prices exist only where annual billing is switched on; do not quote an annual price. Do not quote any plan price in a reply except Essentials, $14.99 a month, to a trader on their own money.$$,
    'fillbook:docs/distribution/PRODUCT_FACTS.md (section 3) + frontend/src/lib/pricingTiers.ts (verified 2026-10-12)', 'verified', now()
  where exists (select 1 from old_pricing)
  returning id
)
update knowledge_documents k
   set trust_level = 'deprecated', superseded_by = (select id from new_pricing)
  from old_pricing
 where k.id = old_pricing.id;

insert into knowledge_documents (topic, title, content, source_doc, trust_level, effective_at)
select 'integrations', 'How trades get into Fillbook (verified 2026-10-12)',
  $$Fillbook builds everything from the trades a trader has imported or synced; it does not see open positions and does not run in real time. Tradovate (OAuth or API key) syncs on a schedule plus a manual Sync now button; Tradovate's fill list can omit very recent fills, so a scheduled sync does not guarantee every fill is caught, and a failed token needs a manual reconnect. NinjaTrader 8 sends each fill through an add-on as fills happen, but only while NinjaTrader is running, and it does not backfill history (import a CSV once for that); the add-on is downloaded from Import and sync with the trader's token already inside. Quantower sends each fill through an add-on indicator while Quantower is running, set up in three steps from Import and sync. Prop firms hosted on Tradovate, or traded in NinjaTrader 8, work through those connectors; this is not tested firm by firm. A Volumetrica (dxFeed Prop) login can pull trade history read-only with Sync now; it is beta, so the first sync should be checked against the platform's own history. Interactive Brokers, ProjectX and TopstepX and PropReports are beta and sync on request. Sierra Chart is beta. Any other broker or platform works by CSV import, and a Google Drive file sync (beta) can pick up exports. Do not describe any other broker as supported, do not say Fillbook works with any broker, and do not name Rithmic direct, DXtrade or the API-broker connectors as available. Alerts warn when a buffer is getting close; they do not block orders.$$,
  'fillbook:docs/distribution/PRODUCT_FACTS.md (section 4) + in-app What''s new (verified 2026-10-12)', 'verified', now()
where not exists (select 1 from knowledge_documents where topic = 'integrations' and trust_level = 'verified');

insert into knowledge_documents (topic, title, content, source_doc, trust_level, effective_at)
select 'what_fillbook_does', 'What Fillbook does, by screen (verified 2026-10-12)',
  $$Everything below is computed from the trader's own imported or synced closed trades, and nothing is advice, a signal or a promise of a result. Trade log: every trade with its setup, size and behavior flags (for example a sized-up trade soon after a loss), with a Review queue that walks the trades still missing a setup, tag, emotion or note one at a time. Reports: results by setup, instrument, time of day, day of week and month, an Edge Score that blends profitability, consistency, risk control and rule adherence, and an Exit efficiency card showing how much of each winner's best open profit was kept (only where a trade carries MFE and MAE data, which today comes from the NinjaTrader add-on). Prop-firm accounts: trailing or static drawdown buffer, today's loss limit remaining, profit target progress, consistency share and minimum trading days per account with an all-accounts overview, using a firm's preset as a starting point to check against the firm's own rules. Simulate: a rule simulator that replays logged trades against a firm's evaluation rules, a pass-probability planner and an expected-value card for whether the next evaluation is worth buying, built from fee, reset and payout numbers the trader enters. Payouts: a payout readiness scan (OK, Warning or Can't tell lines for consistency, minimum days, an optional buffer, news-blackout trades, overnight holding and a possible cross-account hedge, using only the rule values the trader typed in) and a read-only account ledger of fees and payouts with a running balance, recurring monthly fees included, exportable to CSV or Excel. Own money: an own-capital account that logs deposits and withdrawals, a capital curve and drawdown from the account's peak, drawdown odds from the trader's own history, a size-from-account calculator from the percentages the trader picks, cost of trading, and margin and exposure from the margin the trader enters. Also: a Daily Brief, a trading simulator for practice, voice dictation for journal and trade notes through the browser's own speech service, a read-only mentor link scoped to chosen accounts and dates, a connection for AI assistants (beta; Claude Code, Cursor and claude.ai can read the chosen accounts read-only, it is not a trading bot and gives no advice), an in-app assistant, a public sample dashboard and a no-signup simulator demo. Mobile is a progressive web app, not an App Store or Google Play app. Never quote user or trade counts, reviews or ratings.$$,
  'fillbook:docs/distribution/PRODUCT_FACTS.md (sections 5, 6, 6a to 6e) + in-app What''s new (verified 2026-10-12)', 'verified', now()
where not exists (select 1 from knowledge_documents where topic = 'what_fillbook_does' and trust_level = 'verified');
